import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
/**
 * The excluded elements: one CSS selector per line, with the lines the
 * browser can't read listed under the box as they are typed. The forum
 * skips those lines the same way, so a typo never breaks a transition.
 */
export default class ExcludeField extends Component {
  view() {
    const t = (key, params = {}) => app.translator.trans('ernestdefoe-segue.admin.exclude.' + key, params);
    const bad = invalidLines(this.attrs.stream() || '');
    return m("div", {
      className: "Form-group SegueExclude"
    }, m("label", {
      for: "segue-exclude"
    }, t('label')), m("div", {
      className: "helpText",
      id: "segue-exclude-help"
    }, t('help')), m("textarea", {
      id: "segue-exclude",
      className: "FormControl",
      rows: 4,
      spellcheck: false,
      placeholder: t('placeholder'),
      "aria-describedby": "segue-exclude-help",
      bidi: this.attrs.stream
    }), bad.length ? m("p", {
      className: "SegueExclude-invalid",
      role: "status"
    }, t('invalid', {
      selectors: bad.join(', ')
    })) : null);
  }
}

/** The lines document.querySelector rejects. */
export function invalidLines(value) {
  return value.split(/\r?\n/).map(line => line.trim()).filter(line => {
    if (!line) return false;
    try {
      document.querySelector(line);
      return false;
    } catch (e) {
      return true;
    }
  });
}
flarum.reg.add('ernestdefoe-segue', 'admin/components/ExcludeField', ExcludeField);