import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
const BUILT_IN = ['ring', 'dots', 'bars', 'pulse', 'orbit', 'logo'];
const ICONS = 'ernestdefoe-segue.icons';

/**
 * The loading icon setting: a tile for every icon, each one running, with
 * the chosen one outlined. Admins add their own icons from the last tile;
 * uploads are saved at once (the choice itself waits for Save Changes).
 *
 * attrs.icon and attrs.color are the page's setting streams.
 */

const t = (key, params = {}) => app.translator.trans('ernestdefoe-segue.admin.icons.' + key, params);
export default class IconPicker extends Component {
  uploading = false;
  view() {
    const logo = app.forum.attribute('logoUrl');
    return m("div", {
      className: "Form-group SegueIconsGroup"
    }, m("label", null, t('label')), m("div", {
      className: "helpText"
    }, t('help')), m("div", {
      className: "SegueIcons"
    }, BUILT_IN.map(name => name === 'logo' ? logo && this.tile('logo', t('logo'), m("span", {
      className: "SegueIcon SegueIcon--logo",
      style: {
        '--segue-image': cssUrl(logo)
      }
    })) : this.tile(name, t(name), m("span", {
      className: 'SegueIcon SegueIcon--' + name
    }))), this.uploads().map((name, i) => this.tile('file:' + name, t('custom', {
      number: i + 1
    }), m("span", {
      className: "SegueIcon SegueIcon--image",
      style: {
        '--segue-image': cssUrl(this.url(name))
      }
    }), m(Button, {
      className: "Button Button--icon Button--link SegueIcons-remove",
      icon: "fas fa-times",
      "aria-label": t('remove'),
      onclick: () => this.remove(name)
    }))), this.uploadTile()), m("div", {
      className: "helpText"
    }, t('upload_help')));
  }

  /** One icon: a button that picks it, showing it running in the chosen color. */
  tile(value, label, preview, extra) {
    const chosen = this.attrs.icon() === value;
    const color = this.attrs.color();
    const style = /^#(?:[0-9a-f]{3}){1,2}$/i.test(color || '') ? {
      '--segue-color': color
    } : {};
    return m("div", {
      className: "SegueIcons-cell"
    }, m("button", {
      type: "button",
      className: 'SegueIcons-tile' + (chosen ? ' is-active' : ''),
      "aria-pressed": chosen ? 'true' : 'false',
      onclick: () => this.attrs.icon(value)
    }, m("span", {
      className: "SegueIcons-preview",
      style: style
    }, preview), m("span", {
      className: "SegueIcons-label"
    }, label)), extra);
  }
  uploadTile() {
    return m("div", {
      className: "SegueIcons-cell"
    }, m("label", {
      className: 'SegueIcons-tile SegueIcons-upload' + (this.uploading ? ' disabled' : '')
    }, m("span", {
      className: "SegueIcons-preview"
    }, m(Icon, {
      name: this.uploading ? 'fas fa-spinner fa-spin' : 'fas fa-upload'
    })), m("span", {
      className: "SegueIcons-label"
    }, t('upload')), m("input", {
      type: "file",
      accept: "image/gif,image/png,image/webp,image/jpeg",
      hidden: true,
      disabled: this.uploading,
      onchange: e => this.upload(e.target)
    })));
  }
  uploads() {
    try {
      const icons = JSON.parse(app.data.settings[ICONS] || '[]');
      return Array.isArray(icons) ? icons : [];
    } catch (e) {
      return [];
    }
  }
  url(name) {
    return app.forum.attribute('assetsBaseUrl') + '/segue/' + name;
  }
  upload(input) {
    const file = input.files?.[0];
    input.value = '';
    if (!file) return;
    const body = new FormData();
    body.append('icon', file);
    this.uploading = true;
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/segue/icons',
      serialize: raw => raw,
      body
    }).then(response => {
      this.saved(response.icons);
      // Picking what was just added is almost always the point of adding it.
      if (response.added) this.attrs.icon('file:' + response.added);
    }).catch(() => {
      /* app.request already showed the error */
    }).finally(() => {
      this.uploading = false;
      m.redraw();
    });
  }
  remove(name) {
    app.request({
      method: 'DELETE',
      url: app.forum.attribute('apiUrl') + '/segue/icons/' + name
    }).then(response => {
      this.saved(response.icons);
      if (this.attrs.icon() === 'file:' + name) this.attrs.icon('ring');
      m.redraw();
    }).catch(() => {
      /* app.request already showed the error */
    });
  }
  saved(icons) {
    app.data.settings[ICONS] = JSON.stringify(icons);
  }
}

// Our URLs never hold a quote, but keep url("") closed whatever they hold.
function cssUrl(url) {
  return 'url("' + String(url).replace(/["\\\n]/g, encodeURIComponent) + '")';
}
flarum.reg.add('ernestdefoe-segue', 'admin/components/IconPicker', IconPicker);